INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1000, 0, 10, 0, 0, 0, 'Duskwood', 'Duskwood was once called Brightwood, a green and peaceful stretch of the forests south of Stormwind, dotted with farms and hamlets. Then a foul magic seeped into the land, and the woods fell under a night that never fully lifts. The dead do not rest here. The necromancer Morbent Fel commands skeletons and ghouls from the graveyards of Raven Hill, and worgen have appeared as if from thin air to overrun the groves and orchards. Dark Riders out of Deadwind Pass have slaughtered a farmer''s family, and the Defias Brotherhood squats in abandoned farmsteads. When Stormwind recalled its guards, the people of Darkshire raised the Night Watch to defend themselves, and they bitterly resent the capital that left them alone. At the forest''s heart the Twilight Grove keeps a gateway to the Emerald Dream, the realm of the green dragonflight.', 'warcraft.wiki.gg/wiki/Duskwood (originally called Brightwood; Morbent Fel behind the undead; Twilight Grove portal; Dragons of Nightmare); warcraft.wiki.gg/wiki/Brightwood_Grove (Brightwood the original name); quest 146 description (Night Watch formed because Stormwind left when foul magic seeped into the land); quest 56 description (Stormwind retracted its guards); quest 173 reward text (worgen appear out of thin air); quest 95 description (Dark Riders from Deadwind Pass); quest 1244 description (Defias at Addle''s Stead); quest 269 description (Stormwind has forsaken Darkshire); creature_text 270, 271'),
(1001, 1, 10, 1, 0, 0, 'The Hushed Bank', 'The Hushed Bank is the quiet northwestern shore of Duskwood''s river, close to the Westfall border. Here Sven Yorgen keeps a small camp with his companion Lars, far from the safety of Darkshire. They are so few that they cannot spare a man to fetch supplies, and the Carevin family sends what it can with any willing traveler. The two must hunt for their own food, and starving and rabid dire wolves come out of the trees whenever meat is carried back to camp. Venom web spiders and green recluses nest along the bank, and from this lonely post Sven plots against the necromancer to the east.', 'quest 164 description (camp at the northwestern edge, too few to fetch supplies); quest 226 description (Lars, hunting, dire wolves, necromancer to the east); zone_areas: Sven Yorgen 311 and Lars 893 stand in area 1097, with Pygmy Venom Web Spider, Venom Web Spider, Green Recluse, Rabid and Starving Dire Wolf'),
(1002, 1, 10, 2, 0, 0, 'The Darkened Bank', 'The Darkened Bank follows the river that runs the whole length of Duskwood''s northern edge. Starving and rabid dire wolves hunt along it, the rare wolf Lupos among them, while venom web spiders nest between the foothills and the water. Their legs are prized in Darkshire, where the tavern cook turns them into a tangy dish he insists on calling crab cakes. Ghouls and skeletons stray down to the banks from the cemeteries to the south. Between the wolves, the spiders and the restless dead, few travelers care to linger beside these dark waters.', 'zone_areas: area 799 spans the north edge; Starving Dire Wolf x35, Rabid Dire Wolf x22, Pygmy Venom Web Spider, Venom Web Spider, Lupos 521, Brain Eater, Bone Chewer, Skeletal Warder; quest 93 description (spider legs, spiders nest to the north between the foothills and the river, crab cakes); quest 226 description (wolves near the river); quest 245 completion text (men hanging in webs)'),
(1003, 1, 10, 3, 0, 0, 'Addle''s Stead', 'Just south of the road from Westfall, where it first enters Duskwood, stands Addle''s Stead, a farm abandoned to the darkness and then claimed by the Defias Brotherhood. Night runners, night blades and Defias enchanters lurk in its fields, its barn and its little farmhouse, and a Defias strongbox sits among the buildings. The Night Watch counts any Defias presence a threat, and Watcher Backus heard reports that agents of the Brotherhood had gathered here a couple of weeks ago, as though something big had taken place.', 'warcraft.wiki.gg/wiki/Addle''s_Stead (abandoned when darkness spread, taken over by Defias; pre-Cataclysm NPCs); quest 1244 description (Defias gathered at Addle''s Stead, south of the road from Westfall); quest 1245 description (too complex to lead you astray, take it to Trias); quest 1243-1245 titles (The Missing Diplomat); zone_areas: Defias Night Blade 909, Night Runner 215, Enchanter 910, Defias Strongbox in area 536'),
(1004, 1, 10, 4, 0, 0, 'Raven Hill', 'Raven Hill was once a town of western Duskwood, but it has long stood abandoned, its houses empty and its streets given over to the Unseen, shadowy things that drift through the ruins. Lately something else has been seen there. Calor of Darkshire swears the buildings are haunted: two nights running he noticed shadows moving, and on the night before that a light in one of the windows. A goblin trader named Bliztik has found shelter among the deserted buildings, and the graveyard that gives the town its grim fame lies just to the north.', 'warcraft.wiki.gg/wiki/Raven_Hill (abandoned town, haunted by the Unseen, Jitters and Bliztik); warcraft.wiki.gg/wiki/Duskwood (Grand Hamlet and Raven Hill as towns of the region); quest 163 description (Calor saw shadows and a light); quest 5 description (hiding for weeks, grubs and weeds); page_text 246 (abandoned town of Raven''s Hill); zone_areas: Unseen 3094 x11, Jitters 288, Bliztik 2481 in area 94; warcraft.wiki.gg/wiki/Raven_Hill (located in western Duskwood, south of the cemetery); quest 453 request text; quest 266 reward text'),
(1005, 1, 10, 5, 0, 0, 'Raven Hill Cemetery', 'North of the abandoned town sprawls the Raven Hill Cemetery, which by the end of the wars had grown to dominate much of the area. It holds the graves of many who met tragic ends, and few of them lie still. Skeletal horrors walk among the headstones, ghouls such as flesh eaters, bone chewers and rotted ones claw at the earth, and plague spreaders infest the eastern mausoleum. Grave robbers pick over whatever the dead leave behind. One stone bears only the name Eliza and a prayer that the earth might satisfy her hunger, and close by, on the cemetery''s edge, the old hermit Abercrombie keeps his lonely shack.', 'page_text 66 (cemetery near Raven''s Hill now dominated much of the area); warcraft.wiki.gg/wiki/Duskwood (graves of many who have known tragic fates); quest 57, 58 descriptions (skeletal horrors, plague spreaders in the eastern mausoleum); quest 133 description (ghoul types); page_text 731 (Eliza''s Tombstone: Beloved wife, may the earth sate your hunger); quest 157 (shack north of the cemetery); posarea: Abercrombie 289 and Eliza''s Tombstone 37 both in area 492; zone_areas: Skeletal Horror, Plague Spreader, Flesh Eater, Bone Chewer, Rotted One, Grave Robber in 492'),
(1006, 1, 10, 6, 0, 0, 'Forlorn Rowe', 'The Forlorn Rowe is the hill on the northern edge of the Raven Hill Cemetery, and the house at its top is the lair of the necromancer Morbent Fel. From there he looks down on the graves below and commands the dead of Duskwood. Skeletal raiders, warders and healers guard the slopes, and a skeletal officer called Commander Felstrom walks among them. Out past the house lies a weathered grave whose marker reads simply Morgan Ladimore, and the dirt over it has recently been disturbed, a good deal of it displaced.', 'warcraft.wiki.gg/wiki/Forlorn_Rowe (hill on the northern edge of Raven Hill Cemetery, Morbent Fel''s home); quest 55 description (house atop the hill overlooking the cemetery); quest 268 reward text (riders seen speaking with Morbent Fel at the Forlorn Rowe); quest 323 (Skeletal Raiders, Healers, Warders); quest 228 description (buried him out past the house on the hill); quest 225 description (grave recently disturbed); page_text 71 (buried without ceremony); zone_areas: Morbent Fel 1200, Mor''Ladim 522, Commander Felstrom 771, A Weathered Grave 61 in area 243'),
(1007, 1, 10, 7, 0, 0, 'The Yorgen Farmstead', 'In western Duskwood, southeast of Sven Yorgen''s camp, lies the farm he once worked with his wife and children, until Dark Riders out of Deadwind Pass descended on it while he was away and slaughtered his family. Returning, Sven glimpsed a shadowy figure burying something behind an old stump near the barn, but the man fled before he could be caught. The farm was never reclaimed. Defias night runners, night blades and enchanters now lurk around the empty buildings, and young black ravagers prowl the woods around them.', 'quest 95 description (farm to the southeast, Dark Riders, shadowy figure, old stump); quest 230 description (small dirt-stained book); page_text 192-203 (Jitters hid in the barn; Sven left for Darkshire; Riders asked for the Scythe of Elune); warcraft.wiki.gg/wiki/Yorgen_Farmstead (Defias held it, pre-Cataclysm); zone_areas: Defias Night Runner, Night Blade, Enchanter, Young Black Ravager, Mound of loose dirt 59 in area 245'),
(1008, 1, 10, 8, 0, 0, 'Vul''Gol Ogre Mound', 'In southern Duskwood, near where the road turns south toward Stranglethorn Vale, a basin of ruined farmhouses has become the Vul''Gol Ogre Mound, home of the Splinter Fist ogres. Warriors, fire weavers and taskmasters crowd the hollow under a brute named Zzarc''Vul, who wears a monocle large enough to serve as the lens of a stargazing device. The ogres raid beyond their mound as well. When the hermit Abercrombie wandered too far from home picking herbs, a band of them chased him off and carried his crate of tools and herbs back to their lair.', 'warcraft.wiki.gg/wiki/Vul''Gol_Ogre_Mound (basin in southern Duskwood southwest of the road split, ruined farmhouses, Splinter Fist led by Zzarc''Vul); quest 181 description (monocle as the only large enough lens); quest 134 description (ogres stole Abercrombie''s crate); zone_areas: Splinter Fist Warrior, Fire Weaver, Ogre, Taskmaster, Firemonger and Abercrombie''s Crate 119 in area 93'),
(1009, 1, 10, 9, 0, 0, 'Twilight Grove', 'At the heart of Duskwood stands the Twilight Grove, where a great tree rises above a moonwell and a gazebo of night elf design, strange sights so far from Kalimdor. The grove holds one of the few gateways to the Emerald Dream, the realm watched over by the green dragonflight. It is one of four such gateways, each beneath a great tree; the others lie at Seradane in the Hinterlands, Bough Shadow in Ashenvale and Dream Bough in Feralas.', 'warcraft.wiki.gg/wiki/Twilight_Grove (great tree, moonwell, night elf gazebo, one of four Emerald Dream portals, Dragons of Nightmare); creature_text 14890 (Taerar); DB: Taerar 14890 spawn at -10428.8,-392.2, posarea area 856; warcraft.wiki.gg/wiki/Seradane, Bough_Shadow, Dream_Bough (the other three great trees with Emerald Dream portals)'),
(1010, 1, 10, 10, 0, 0, 'The Rotting Orchard', 'Southwest of Darkshire the orchards of Duskwood have gone to rot, and the worgen have overrun them. Nightbane dark runners, which make up the bulk of the worgen packs, roam between the twisted trees alongside shadow weavers, and the Unseen drift through the gloom. Hunters of the Carevin family come here to thin their numbers. Just to the east lies the mine called Roland''s Doom, where the worgen were first found, and where the fiercest of them now make their den around their bonfires.', 'quest 221 description and reward text (Dark Runners bulk of worgen, overrun the Rotting Orchard southwest of town, numbers refill); quest 173 description (Shadow Weavers in Brightwood Grove and the Rotting Orchard); quest 222 description (Vile Fangs and Tainted Ones near caves and in the mine to the south, bonfires); quest 1043 description (mine to the south where worgen were first found); warcraft.wiki.gg/wiki/Roland''s_Doom (due east of the Rotting Orchard); zone_areas: Nightbane Dark Runner x34, Shadow Weaver x13, Unseen in area 241'),
(1011, 1, 10, 11, 0, 0, 'Brightwood Grove', 'West of Darkshire the forest opens into Brightwood Grove, a name kept from the days when the whole wood was called Brightwood. Nothing bright remains. Nightbane worgen keep camps throughout the grove, shadow weavers and dark runners among them, and the dreaded worgen Fenros stalks between them. Black ravagers and their mastiffs hunt in packs across the fields, and green recluse spiders spin in the trees. Calor of the Carevin family, scoffing at the name, sends those who would join his master''s cause here first to prove themselves against the worgen.', 'warcraft.wiki.gg/wiki/Brightwood_Grove (west of Darkshire, Brightwood the original name, worgen camps, Fenros); quest 173 description (Brightwood Grove, bright, hah!); zone_areas: Nightbane Worgen x25, Dark Runner x23, Shadow Weaver x14, Fenros 507, Black Ravager, Black Ravager Mastiff, Green Recluse in area 242'),
(1012, 1, 10, 12, 0, 0, 'Darkshire', 'Darkshire, once called Grand Hamlet, took its grim name after darkness fell on the forest. It is the heart of human Duskwood and the home of the Night Watch. Lord Ello Ebonlocke governs from the town hall with a council that complains endlessly of Stormwind''s neglect, while Commander Althea Ebonlocke leads the watchers. Clerk Daltry keeps the town registry, the Scarlet Raven Tavern serves Chef Grual''s spider leg crab cakes, Madame Eva reads the cards beside the square, and the Carevin family plots its own war on evil. The stargazer Viktori seeks answers in the sky, certain that a truth beyond magic can explain the forest''s strange transformation.', 'warcraft.wiki.gg/wiki/Darkshire (originally Grand Hamlet, renamed after the corruption); page_text 67 (Darkshire, as it was now called); quest 145 description (Darkshire in the heart of Duskwood); creature_text 269, 270, 271 (council members); quests 66, 67, 78, 93, 148, 223; quest 174 description (Viktori, truth beyond magic); quest 9429 (Anchorite Delan 17104); zone_areas: all named NPCs above in area 42; warcraft.wiki.gg/wiki/Darkshire (Grand Hamlet renamed Darkshire, cited to Warcraft: Legends Volume 2, Warrior: Divided, 2008)'),
(1013, 1, 10, 13, 0, 0, 'Tranquil Gardens Cemetery', 'Just south of Darkshire lies the Tranquil Gardens Cemetery, whose name has become a bitter joke. Skeletal warriors and mages rise among the graves, and the Night Watch sends its first volunteers here to cut them down before they reach the town. A deranged ghoul haunts the ruined church. In the hills nearby stands the old farmhouse of Blind Mary, a spirit who tore out her own eyes and believes herself a monster, and who still begs visitors not to look at her. She once threw her prized looking glass away behind the barn, and rumor says the ghoul may have picked it up.', 'quest 56 description (Tranquil Gardens just south of Darkshire, Skeletal Warriors and Mages); warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery (Blind Mary''s house just north, Insane Ghoul in the ruined church); quest 177 description (looking glass discarded behind the barn, Insane Ghoul may have picked it up); quest 149 description and completion text (Blind Mary tore out her eyes, please look away); zone_areas: Skeletal Warrior x15, Skeletal Mage x12, Insane Ghoul 511 in area 121; quest 154 description (I''m a monster)'),
(1014, 1, 10, 14, 0, 0, 'Manor Mistmantle', 'Just north of Darkshire stands Manor Mistmantle, the house of the recluse Stalvan Mistmantle. The grounds have gone to rot. Fetid corpses shamble along the overgrown paths and around the house, and the Unseen drift nearby. Only one living thing seems to thrive there, a single flower in the garden called the Tear of Tilloa. Its master is no welcoming host. He meets intruders with threats to spill their blood, and sometimes, peering at them, mistakes them for someone named Tilloa.', 'quest 98 description (his cottage just north of town); warcraft.wiki.gg/wiki/Manor_Mistmantle (rotten grounds, minions, single flower Tear of Tilloa); quest 80 description (I have had my eye on that creep for quite some time); page_text 20-24 (Tilloa); zone_areas: Stalvan 315, Fetid Corpse x14, Unseen, Tear of Tilloa 321 in area 1098; creature_text 315 (I shall spill your blood; Tilloa is that you?)'),
(1015, 1, 10, 15, 0, 0, 'Beggar''s Haunt', 'In the northeast of Duskwood, close to the road into Deadwind Pass, stands Beggar''s Haunt, an abandoned scout tower of the Stormwind Guard. Its new tenants are Forsaken. Deathstalker Zraedus and Apothecary Faustin of the Royal Apothecary Society belong to an expeditionary force sent at Varimathras''s command to survey the southern lands, and they would rather nobody knew they were here. When a human infiltrator was caught spying on the tower and carried off to the orcs of Stonard, they resolved to help their orcish allies, after their own fashion, and Faustin set about brewing a truth serum for the prisoner.', 'warcraft.wiki.gg/wiki/Beggar''s_Haunt (abandoned Stormwind Guard scout tower, Zraedus and Faustin, pre-Cataclysm); quest 1372 description (expeditionary force at Varimathras''s behest, infiltrator spying on Beggar''s Haunt, taken to Stonard); quest 1372 reward text (last thing we need is a busybody); quest 1383 reward text (prepare the pois- I mean the truth serum); zone_areas: Apothecary Faustin 5414, Deathstalker Zraedus 5418, Faustin''s Alchemy Set in area 576; quest 1383 request text'),
(1016, 2, 10, 1, 1, 0, 'Commander Althea Ebonlocke', 'Commander Althea Ebonlocke leads the Night Watch, the militia Darkshire raised for itself after Stormwind withdrew its commissioned guards. She has never had enough watchers, and she warns every traveler to keep to the roads and move only by day. The defense of the town comes before everything, and she has little patience for dead end leads. She sends volunteers against the undead of the cemeteries, and against Mor''Ladim, a wandering undead who attacks her watchmen on patrol and has slain some of her strongest watchers.', 'npc_text 50029 (stick to the roads, travel by day, numbers small); quest 56 description; quest 58 description (not enough watchers); quest 79 completion text (Darkshire''s defense is my priority, no time for dead-end leads); quests 80, 97, 98; quest 228 description and completion text; quest 227 reward text (attacking Watchmen on patrol)'),
(1017, 2, 10, 2, 1, 0, 'Lord Ello Ebonlocke', 'Lord Ello Ebonlocke is the Mayor of Darkshire, presiding over its council from the town hall. He has no illusions about his town''s position. Undead crawl all over the land, he says, and the Night Watch alone cannot protect Darkshire forever; it needs the backing of the Stormwind Army, whose guards were withdrawn from the town and left it to its own devices. He passes sentence on the worst of criminals, condemning to death a man who sold corpses to Morbent Fel, though Stormwind''s House of Nobles chose to keep the villain in a cell instead.', 'quest 146 description; creature_text 263; quest 377 description (Lord Ebonlocke''s sentence on Dextren Ward); quest 160 completion and reward text (does not know Abercrombie, ancient language); quests 251, 252, 253; quest 56 description (Stormwind retracted its guards); creature_text 263 (Where is the Stormwind Army; the Night Watch alone cannot protect us)'),
(1018, 2, 10, 3, 1, 0, 'Madame Eva', 'Madame Eva reads the cards and listens to the whispers of spirits from her home on the Darkshire square. The stars, she says, speak of horrors waiting in the night. When a disturbance rippled through her veins she knew her granddaughter Alyssa was in danger, and Death stared up at her from the table. A long trance gave her one name, Stalvan, and she fears for them all. She practices other old arts too, spinning thread from ghost hair that can bind spirits, and enchanting totems that punish anyone who raises a hand against their bearer.', 'quest 66 description (Alyssa, cards, trance, Stalvan); quest 98 reward text; quest 148 description (her home on the Darkshire square); quests 149, 157 (Ghost Hair Thread binds evil spirits); quest 101 description and reward text; creature_text 265; DB: Alyssa Eva 1673 in Darkshire'),
(1019, 2, 10, 4, 1, 0, 'Sven Yorgen', 'Sven Yorgen farmed land in western Duskwood until the day he went to Darkshire and came home to find his wife and children murdered by Dark Riders from Deadwind Pass. He rode after the killers, and so never learned what the shadowy figure he glimpsed by his barn had buried. Now he keeps a small camp on the Hushed Bank with his companion Lars, living off the land, short of men and welcoming anyone who will join his fight. Dangerous days lie ahead, Lars says, with the necromancer to the east.', 'quest 95 description; page_text 193 (Sven left his farm for Darkshire); quest 164 description and completion text; quest 226 description; quest 268 reward text; quest 323 description; quest 55 description (be the instrument of my revenge)'),
(1020, 2, 10, 5, 1, 0, 'Jitters', 'Jitters is a nervous, starving fugitive who hides in the empty town of Raven Hill. He has lived there for weeks on grubs and weeds, and he would trade well for a decent meal; he has heard that Chef Grual''s crab cakes in Darkshire are very good. Strangers terrify him. Found, he begs not to be killed and swears there are no monsters in Raven Hill, only harmless Jitters, yet he insists that they are everywhere and that he cannot escape them.', 'page_text 85, 186-203, 246 (Jitters'' Completed Journal); quest 163 reward text; quest 5 description; quest 453 reward text; quest 268 description; warcraft.wiki.gg/wiki/Jitters (a member of the Defias Brotherhood infiltrating Duskwood); quest 163 reward text (only harmless Jitters)'),
(1021, 2, 10, 6, 1, 0, 'Jonathan Carevin', 'Jonathan Carevin heads the Carevin family of Darkshire, hunters of demons, undead and other monstrosities who wage their own war against evil in the forest. He is a busy and suspicious man who trusts no one unwilling to aid the cause, and he watches the townsfolk for any who give comfort to the enemies of the Light. Among his followers is Calor, who joined the family in disgust at the complacency of the Night Watch. Calor tests recruits against the worgen and recommends the worthy to his master.', 'quest 1042 description (Carevin family, hunters of demons, undead and monstrosities; Jonathan head of the household); quest 223 reward text (cold reception, trust none); page_text 63 (Calor''s Note, townsfolk under suspicion); quest 173 description (Calor disillusioned by the Watch); quest 1043 reward text (influence not large enough, contain the worgen)'),
(1022, 2, 10, 7, 1, 0, 'Abercrombie', 'Abercrombie is a frail old man who lives alone in a shack beside the Raven Hill Cemetery. He once came to Darkshire often for supplies, but has not been seen there in a long while; the roads are dangerous, he says, and he is not getting any younger. He seems harmless enough, asking travelers for ghost hair thread to string across his door and windows, strong liquor for the cold nights, ghoul ribs for an effigy against the ghouls, and a crate of tools stolen by ogres. Yet he laughs a little too hard when they succeed, and more than once his tongue slips, as if about to thank some darker power.', 'quest 165 description and reward text; quests 148, 157, 158, 159, 133, 134 (requests; Thank the Nec-); quest 160 description (Hahahaha); quest 253 description (the Embalmer, Eliza, his heart); page_text 235 (signed The Embalmer); warcraft.wiki.gg/wiki/Abercrombie (necromancer, the Hermit and the Embalmer, pre-Cataclysm location); quest 134 reward text (Thank the Nec-); quest 159 reward text (your foolish-)'),
(1023, 2, 10, 8, 0, 0, 'Stalvan Mistmantle', 'Stalvan Mistmantle of Silverpine was once a scholar, an apprentice of Headmaster Crillian, who travelled south and stayed in Moonbrook to tutor the farm children, until troubles in the region forced him to abandon his post as headmaster of its new schoolhouse. Now he lives as a recluse in a rotting manor just north of Darkshire, where a single flower called the Tear of Tilloa grows in the garden. He greets intruders with threats to spill their blood, and sometimes, peering at them, takes them for someone named Tilloa.', 'page_text 16-19 (letters to Crillian, Moonbrook Schoolhouse, Stalvan Mistmantle of Silverpine); page_text 20-24 (Tilloa, begonia, suitor, nice old man, blood I shall spill); quest 72 description (Flintridge trust, massacre); quest 79 description (visiting nobles slaughtered); quest 98 description; creature_text 315 (Tilloa is that you?); warcraft.wiki.gg/wiki/Stalvan_Mistmantle (pre-Cataclysm section)'),
(1024, 2, 10, 9, 0, 0, 'Morbent Fel', 'Morbent Fel is the necromancer behind the undead plague of Duskwood. From his house atop the Forlorn Rowe he looks down on the Raven Hill Cemetery, and the skeletons and ghouls that fill it answer to his will, while skeletal raiders, warders and healers guard the slopes below him. He has human accomplices too: Dextren Ward was caught selling him bodies from the cemetery and condemned to death for it by Lord Ebonlocke. At their lonely camp on the Hushed Bank, Sven Yorgen and his companion Lars count the necromancer their enemy.', 'warcraft.wiki.gg/wiki/Morbent_Fel (pre-Cataclysm: ruled the undead of Duskwood, magical barrier, Morbent''s Bane); quest 55 description; quest 268 reward text; quest 323 description (ally to the dark riders); quest 377 description (Dextren Ward); quest 269 reward text; quests 270, 321 (Third Fleet, Flying Osprey); quest 322 description; quest 226 description and reward text (Lars and Sven against the necromancer)'),
(1025, 2, 10, 10, 0, 0, 'Mor''Ladim', 'Mor''Ladim is the name taken by an undead knight who wanders Duskwood, following a strange and meandering path through the Raven Hill Cemetery and the woods around it. He kills without reason, attacking watchmen on patrol and travelers alike, and some of the Night Watch''s strongest watchers have been lost to him. Darkshire wants him laid to rest, but Commander Ebonlocke has no one to spare for the task and can only wish luck to those who try.', 'page_text 64-72 (The Story of Morgan Ladimore); quest 227 reward text (attacking watchmen on patrol and killing people); quest 228 description; quest 229 description (Sarah Ladimore lived); quest 228 description and completion text'),
(1026, 3, 10, 1, 1, 0, 'The Night Watch', 'When Stormwind recalled its commissioned guards, Darkshire formed the Night Watch from its own people, and Commander Althea Ebonlocke has never had enough of them. She sends volunteers first against the skeletons of the Tranquil Gardens Cemetery, then against the walking dead of Raven Hill, and finally into the eastern mausoleum to purge the plague spreaders. Watchers at a camp out on the road fight spiders that have strung up their comrades in webs. The town''s anger at Stormwind runs deep. When the House of Nobles imprisoned the corpse seller Dextren Ward rather than behead him as Lord Ebonlocke had sentenced, Councilman Millstipe offered a reward for the villain''s hand, a message to the nobles that Duskwood would not be ignored.', 'quests 56, 57, 58 (descriptions and reward texts); quest 245 description and completion text; DB: Watcher Dodds 888 at the road camp at -10923,-385; quests 145, 146 (descriptions and reward texts); quest 377 description and reward text'),
(1027, 3, 10, 2, 1, 0, 'The Legend of Stalvan', 'It begins with Madame Eva''s dread. A horrible disturbance rippled through her veins one night, and she knew her granddaughter Alyssa was in great danger; Death stared up at her from the cards. A long, dark trance gave her one clue, the name Stalvan, and she sends whoever will help to the clerk in the town hall. Clerk Daltry''s registry holds a record of one Stalvan Mistmantle, last recorded at the Moonbrook Schoolhouse in Westfall, an address so outdated that he would be glad of any news to keep his records clean.', 'quests 66, 67, 68, 69, 70, 72, 74, 75, 78, 79, 80, 97, 98 (descriptions and reward texts); page_text 16-24'),
(1028, 3, 10, 3, 1, 0, 'Worgen in the Woods', 'Worgen have come to Duskwood, overrunning Brightwood Grove and the Rotting Orchard, and no one in Darkshire can say why. Calor of the Carevin family tests would-be recruits against them: first the shadow weavers of the grove and the orchard, then the dark runners who make up the bulk of the packs, and at last the vile fangs and tainted ones who den near the caves and in the mine to the south, whose bonfires can be seen from far away. The worthy earn his recommendation to Jonathan Carevin. Those who come to town asking about the wolf-men are sent to Jonathan too, for the Carevins hunt demons, undead and every other monstrosity.', 'quests 173, 221, 222, 223 (descriptions and reward texts); quests 1041, 1042, 1043, 1044; creature_text 3946 (Velinde Starsong: scythe granted to fight the demons of Felwood; worgen run rampant, scythe lost); page_text 185-190 (Jitters found the scythe in Roland''s Doom, worgen came); warcraft.wiki.gg/wiki/Roland''s_Doom and Scythe_of_Elune (Velinde died at Roland''s Doom); gameobject 19030 Mound of Dirt at Roland''s Doom, event_script 664 summons Velinde Starsong''s spirit (3946) there'),
(1029, 3, 10, 4, 1, 0, 'Sven''s Revenge', 'Sven Yorgen has one thing to ask of those who would help him. While he was away in Darkshire, Dark Riders from Deadwind Pass descended on his farm in western Duskwood and slaughtered his family. When he returned he saw a shadowy figure skulking near the barn, burying something, but the man fled, and Sven, hot on the heels of the riders, could not stay to look. Whatever was hidden lies behind the old stump near his barn, and he would be grateful to anyone who finds it.', 'quests 95, 230, 262, 265, 266, 453, 268, 323, 269, 270, 321, 324, 322, 325, 55 (descriptions and reward texts); quest 323 description'),
(1030, 3, 10, 5, 1, 0, 'Bride of the Embalmer', 'The Carevins worry about an old man who used to come into town often for supplies but has not been seen in a long while, and those sent to check on him find Abercrombie in his shack overlooking the Raven Hill Cemetery, glad of help. The roads are dangerous, he says, and he is not getting any younger. He wants ghost hair thread, which Madame Eva spins from a comb run through Blind Mary''s hair; Zombie Juice from the Scarlet Raven, brewed from rot blossoms grown in skeletons'' skulls; ghoul ribs for an effigy; and a crate of tools the ogres stole. Then he sends a cheerful note to his old friend, the mayor.', 'quests 165, 148, 149, 154, 157, 158, 156, 159, 133, 134, 160, 251, 401, 252, 253 (descriptions and reward texts); page_text 235 (Translated Letter from The Embalmer); creature_text 468 (Town Crier during the Stitches event); smart_scripts 263 and 412 (finishing quest 252 starts the Stitches march)'),
(1031, 3, 10, 6, 1, 0, 'A Daughter''s Love', 'On the outskirts of the Raven Hill Cemetery, out past the necromancer''s house on the Forlorn Rowe, stands a lonely grave apart from the rest. Its weathered marker reads simply Morgan Ladimore, with no epitaph and no prayer. The dirt over the grave has been recently disturbed, and a good deal of it seems to have been displaced. Whoever Morgan Ladimore was, Darkshire laid him to rest far from its tended graves. The town''s historian, Sirra Von''Indi, may remember the name.', 'quests 225, 227, 228, 229, 231 (descriptions and reward texts); page_text 64-72');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(1000, 1, 2, 255, 'Of late the Twilight Grove has become a place to shun. Dragons of the green flight, twisted and driven mad by nightmare, have come out through the gateway to guard it, one more terror in a forest that already has too many.', 'warcraft.wiki.gg/wiki/Duskwood (Dragons of Nightmare at the Twilight Grove); DB: Taerar 14890 spawn at -10428.8,-392.2, posarea area 856; mod-individual-progression ipp_aware_npcs.sql (Dragons of Nightmare 14887-14890 phaseMask IPPPHASE) and IndividualProgression.cpp checkIPPhasing (AREA_TWILIGHT_GROVE 856: IPP_PHASE cast once PROGRESSION_ONYXIA, state 2, is passed)'),
(1004, 1, 0, 255, 'The haunting of Raven Hill is no monster. The moving shadows and the light in the window belong to Jitters, a terrified fugitive who has taken refuge among the empty houses. He shrinks from every stranger, begging to be left alone, sure that whatever hunts him is everywhere and that he cannot escape it.', 'quest 163 reward text (No! Please don''t kill me! It''s just me... Jitters); quest 5 description (hiding for weeks, grubs and weeds)'),
(1006, 1, 0, 255, 'The house has had visitors. Sven Yorgen has seen the Dark Riders of Deadwind Pass in Duskwood, the same riders who slaughtered his family, and has watched them speak with Morbent Fel here at the Forlorn Rowe.', 'quest 268 reward text; quest 323 description (ally to the dark riders)'),
(1006, 2, 0, 255, 'The grave out past the house belongs to the knight Morgan Ladimore. After he took his own life in grief, Darkshire buried him here quickly and without ceremony, on the outskirts of the cemetery. Only days later the grave was disturbed, and his body could not be found.', 'page_text 70-71 (The Story of Morgan Ladimore, given on accepting quest 227); quest 228 description (buried him out past the house on the hill)'),
(1007, 1, 0, 255, 'Behind the stump lies a mound of dirt, piled up in haste by someone with little time to hide what he carried. Buried in it is a small, dirt-stained book with no title, and when Sven read its pages he slammed it shut: its writer had witnessed the slaughter of his family.', 'quest 95 reward text (mound hastily piled up); quest 230 description (small dirt-stained book); quest 230 reward text (a witness to my family''s death)'),
(1007, 2, 0, 255, 'The witness was a fugitive who had hidden in Sven''s barn for days without making himself known. His completed journal tells what the riders wanted. Before the killing began they demanded the Scythe of Elune of Sven''s wife. She bravely claimed to know it, hoping to lead them away from her children, but a power working through a rider''s gem found her lie, a voice declared that the Lord had spoken, and the family was killed.', 'page_text 192-203 (Jitters'' Completed Journal, item 2560, given on accepting quest 268)'),
(1009, 1, 2, 255, 'Yet the grove is no refuge. Dragons of Ysera''s flight, corrupted and driven mad by nightmare, have come out to guard the portal and to spread their madness. The great green dragon Taerar has been seen here, crying that peace is but a fleeting dream and loosing his children of madness upon the world.', 'warcraft.wiki.gg/wiki/Twilight_Grove (Dragons of Nightmare); creature_text 14890 (Taerar); DB: Taerar 14890 spawn at -10428.8,-392.2, posarea area 856; mod-individual-progression ipp_aware_npcs.sql (Dragons of Nightmare 14887-14890 phaseMask IPPPHASE) and IndividualProgression.cpp checkIPPhasing (AREA_TWILIGHT_GROVE 856: IPP_PHASE cast once PROGRESSION_ONYXIA, state 2, is passed)'),
(1012, 1, 8, 255, 'Help has come from much farther away as well. Anchorite Delan of the draenei, whose people have joined the Alliance, waits in Darkshire to greet the draenei sent to aid the town, for these poor souls are beset on all sides by the creatures of the night.', 'quest 9429 description and reward text (Travel to Darkshire, draenei only); DB: Anchorite Delan 17104 in Darkshire'),
(1014, 1, 0, 255, 'The manor hides a murderer. Stalvan, once a scholar and tutor, became obsessed with Tilloa, the daughter of the noble family he served, and when she chose another his longing turned to blood. The Night Watch had kept a suspicious eye on the house for some time before proof of its master''s guilt was found, and Commander Ebonlocke ordered him executed.', 'quest 98 description; quest 80 description (I have had my eye on that creep); page_text 20-24 (Tilloa)'),
(1015, 1, 0, 255, 'Faustin''s serum, he promises, will deal with the truth precisely as the truth should be dealt with. The infiltrator, he chuckles, will surely open up once he drinks it, and as he readies the brew he nearly calls it poison before correcting himself.', 'quest 1383 description and reward text (prepare the pois- I mean the truth serum); quest 1391 description (mixed into ale, keep it quiet)'),
(1016, 1, 0, 255, 'One man had long troubled her: Stalvan Mistmantle, the creep in the manor north of town, on whom she had kept a wary eye for some time. When a trail of letters and journal pages, matched by Clerk Daltry to the registry signature, proved his guilt, she knew her suspicions had been right, and she ordered the murderer executed once and for all.', 'quest 80 description; quest 97 reward text (I knew it!); quest 98 description'),
(1016, 2, 0, 255, 'When Mor''Ladim was finally struck down, she thanked his slayer on behalf of Darkshire and then confessed what she should have said earlier. Morgan Ladimore, whose undead body Mor''Ladim was, had believed his whole family dead, but his daughter Sarah lived, and now serves as a Watcher, always troubled by the circumstances of her father''s death.', 'quest 228 reward text; quest 229 description'),
(1017, 1, 0, 255, 'A note came to him from a hermit named Abercrombie, a man he had never heard of, written in a script too ancient to read. Translated by the historian Sirra Von''Indi, it was a gloating confession from one who signed himself the Embalmer and had tricked his helpers into building a fiend of flesh, bone and twisted metal. Ello went white, and told the bearer that their kindness had doomed the town.', 'quest 160 completion and reward text; page_text 235 (Translated Letter from The Embalmer); quest 252 reward text'),
(1017, 2, 0, 255, 'The Embalmer, Ello knew, was a name from Darkshire''s children''s stories, and he sent for the heart the hermit had placed in his dead wife Eliza. When it came back from her grave still beating, he declared it proof against the Embalmer''s evil and a powerful aegis over Darkshire, and promised the deed a place in the town''s annals forever.', 'quest 253 description and reward text'),
(1018, 1, 0, 255, 'Her premonition proved true. The trail it began led to Stalvan Mistmantle, a murderer living just north of Darkshire, and when he was slain she knew it before his family ring was laid before her: a wave of hope had rippled through the tainted forest. Duskwood was free of his bloodthirst at last, though her joy was hampered by thoughts of those who fell prey to him.', 'quest 98 description and reward text'),
(1019, 1, 0, 255, 'The buried book led at last to its author, and his completed journal set Sven on the path against the riders. He had seen them in Duskwood, speaking with the necromancer Morbent Fel at the Forlorn Rowe, and Fel''s death became his revenge, though he would send no one against so vile a fiend without first testing their skill against his minions.', 'quest 268 reward text; quest 323 description'),
(1019, 2, 0, 255, 'Morbent Fel was defeated. The Dark Riders are still at large, Sven admits, but a small piece of what he had hoped beyond hope has come to pass, and he promised that the deed would live forever in the legends of Duskwood. Perhaps, he said, fate would one day bring his avenger back to him.', 'quest 55 reward text'),
(1020, 1, 0, 255, 'Jitters is the shadowy figure Sven Yorgen glimpsed by his barn on the night his family died. Cornered at last, he owned that the half finished book buried behind the stump was his, and warned that whoever had read it knew only half the tale.', 'quest 453 reward text; quest 268 description (left it at Sven''s farm when I fled)'),
(1020, 2, 0, 255, 'His completed journal tells the rest. Digging in the mine called Roland''s Doom, with the Defias Brotherhood pleased with the work, he pulled a rune-carved scythe from the rubble, and worgen fell on the miners from every side. He believes he alone escaped, saved perhaps by the caution that gave him his nickname. Hiding in Sven''s barn, he watched riders hunting that very scythe kill the family, and has fled from hiding place to hiding place since. Rather than face Sven, he gave the journal up.', 'page_text 85, 186-203, 246 (Jitters'' Completed Journal, item 2560); quest 268 description'),
(1021, 1, 0, 255, 'He judged true the stranger''s tale of a night elf priestess, and pointed to the mine to the south, where the worgen were first found. Hearing what lay there, he admits that the Carevins lack the influence to find the root of these troubles and end them once and for all, but they will contain the worgen''s numbers in Duskwood, and he has made it Calor''s first priority. For the priestess who brought this evil into the woods, he bears no ill will.', 'quest 1043 description and reward text; quest 1044 description'),
(1022, 1, 0, 255, 'His note to Lord Ebonlocke, once translated, gave him away. It was a gloating confession signed the Embalmer. The hermit called himself a creator, and he had fooled his helpers into aiding his latest and most dire creation, a fiend of flesh, bone and twisted metal now waiting outside his dwelling for his word to go forth and slaughter.', 'page_text 235 (Translated Letter from The Embalmer); quest 252 description and reward text'),
(1022, 2, 0, 255, 'The Embalmer is a name from Darkshire''s children''s stories, and the story is true. He was once a kindly alchemist, driven mad by the death of his wife Eliza. To restore her he used dark magic to place his own heart within her body. It revived her, but cursed her with a hunger for human flesh, and he had to keep her buried. His heart is his power.', 'quest 253 description; page_text 731 (Eliza''s Tombstone)'),
(1022, 3, 0, 255, 'That heart was dug out of Eliza''s grave, still beating, and carried to Lord Ebonlocke. With it the Embalmer''s power was broken, and its magic became a powerful aegis over the town he had meant to see slaughtered.', 'quest 254 reward text (the coffin); quest 253 reward text'),
(1023, 1, 0, 255, 'Leaving Moonbrook, Stalvan became tutor to the children of the noble Flintridge family, and his journal shows what followed. The boy Giles was rambunctious, but the elder daughter, Tilloa, was exceptionally bright, and he could not help noticing her beauty, though her father had arranged her marriage for the coming year. When she placed a scarlet begonia in his palm and smiled, his heart trembled, and he took it for love.', 'page_text 18-19 (application for a tutor''s post); page_text 20 (Torn Journal Page, item 916, quest 74); page_text 21 (Faded Journal Page, item 921, quest 75)'),
(1023, 2, 0, 255, 'The later pages turn dark. Sure that she shared his feelings, he was enraged when Tilloa introduced him to her suitor as her tutor, a nice old man, and when she was engaged his despair became a vow of blood. The Flintridge estate had once seen a massacre, and Tavernkeep Smitts had found the muddy pages while investigating the slaughter of visiting nobles, a crime never tied to the crazy man in the woods until Clerk Daltry matched the journal''s hand to Stalvan''s registry signature, proving his guilt beyond doubt.', 'page_text 22-24 (Muddy Journal Pages 938, Bloodstained Journal Page 939); quest 72 description (massacre at the Flintridge estate); quest 79 description (visiting nobles slaughtered); quest 80 reward text'),
(1023, 3, 0, 255, 'Stalvan Mistmantle is dead, cut down in his own manor north of Darkshire. The scholar who once taught farm children in Moonbrook will threaten no one again, and the recluse who mistook strangers for Tilloa is silent at last.', 'quest 98 reward text; creature_text 315'),
(1024, 1, 0, 255, 'Fel keeps company with the Dark Riders of Deadwind Pass. Sven Yorgen has seen the riders who slaughtered his family speaking with the necromancer at the Forlorn Rowe, and the journal that told him why they killed has set him on the path against them.', 'quest 268 reward text; quest 323 description'),
(1024, 2, 0, 255, 'Bishop Farthing of Stormwind, reading of the evil taint that has taken hold in Duskwood, judged the necromancer immensely powerful. Fel has cast dark enchantments about himself to protect him from physical assaults, and whoever means to defeat him must first carry a weapon that is proof against those protections.', 'quest 269 reward text'),
(1024, 3, 0, 255, 'Morbent Fel has fallen, slain in his house above the Raven Hill Cemetery, and the master of Duskwood''s restless dead no longer looks down on the graves from the Forlorn Rowe.', 'quest 55 reward text'),
(1025, 1, 0, 255, 'He was once Morgan Ladimore, a noble knight of Duskwood who fought beside Uther the Lightbringer in the wars of Lordaeron. He came home to find his house in ruins and his wife Lys beneath a gravestone at Raven Hill. Mad with grief, he cut down three cemetery attendants who tried to restrain him, then turned his knife on himself. Buried without ceremony, he rose only days later.', 'page_text 64-72 (The Story of Morgan Ladimore, given on accepting quest 227); quest 227 reward text'),
(1025, 2, 0, 255, 'Mor''Ladim has been struck down among the graves he haunts. The undead knight who cut down watchmen and travelers without reason lies still at last, and the patrols of the Night Watch have one less terror to face on the roads around Raven Hill.', 'quest 228 reward text (there is one small matter)'),
(1025, 3, 0, 255, 'Morgan never knew that one of his children had lived. His daughter Sarah now serves as a Watcher, and she sent her ring to his grave so that he might know she was well and that none of them held him to blame. His spirit found peace at last, gave up his sword Archeus to the one who brought him word, and spoke his wife''s name as it was put to rest.', 'quest 229 description; quest 231 description and reward text'),
(1026, 1, 0, 255, 'The cemeteries were scoured and the plague spreaders cut down in the eastern mausoleum. On behalf of the people of Darkshire, Althea thanked the volunteers for their bravery and dedication, for her watchers alone are still too few to keep the town safe.', 'quest 58 description and reward text'),
(1026, 2, 0, 255, 'Dextren Ward paid for his crimes at last, slain in the Stormwind Stockade and his hand carried back to Darkshire. Millstipe was delighted: the families of the dead had their peace, and the corrupt bureaucrats of the House of Nobles had their message. Stormwind, he warned, must rise to the needs of Duskwood''s people, or Duskwood will break free from its tyranny.', 'quest 377 reward text'),
(1027, 1, 0, 255, 'In an old footlocker at the Moonbrook Schoolhouse lay an unsent letter from Stalvan to his old master, Headmaster Crillian, full of happy days tutoring the farm children while the town mayor built him a school. Looking again, Daltry found a second address beneath the first, half scratched out: the Lion''s Pride Inn in Goldshire.', 'quest 67, 68 descriptions and reward texts; page_text 16-17; quest 69 description'),
(1027, 2, 0, 255, 'Innkeeper Farley remembered a messenger who fled screaming into a stormy night years before, leaving his letters behind. One, from Stalvan, was bound for the Canal District of Stormwind, where Caretaker Folsom of the Flintridge estate took it ill. His father had mopped up the blood after the massacre there, and now the family''s last possessions are headed for auction.', 'quest 70 description and reward text; page_text 18-19; quest 72 description'),
(1027, 3, 0, 255, 'Journal pages turned up in the Flintridge crate, in a chest at old Marshal Haggard''s house, and in the keeping of Tavernkeep Smitts in Darkshire, who had followed the legend of Stalvan for years. They told of a tutor''s obsession with the Flintridges'' daughter Tilloa, and of his fury when she chose another. Smitts and Haggard had investigated when visiting nobles were slaughtered, but never linked the handwriting to the crazy man in the woods.', 'quests 74, 75, 78 descriptions and reward texts; quest 79 description; page_text 20-23'),
(1027, 4, 0, 255, 'Commander Ebonlocke had long kept an eye on Stalvan, and Daltry, expert in handwriting after his years with the registry, matched the pages to the registry signature. Her suspicions were proved. The recluse of the manor north of town had led a life of depravity, innocent victims had died by his hand, and she ordered him executed once and for all.', 'quest 79 reward text; quests 80, 97 descriptions and reward texts; quest 98 description'),
(1027, 5, 0, 255, 'Stalvan Mistmantle was slain in his manor, and his family ring went to Madame Eva, whose premonition had begun the hunt. She already knew. A wave of hope had rippled through the tainted forest, and Duskwood was free of his bloodthirst, though her joy was hampered by thoughts of those who fell prey to him.', 'quest 98 reward text'),
(1028, 1, 0, 255, 'The packs do not thin. The worgen seemed to appear out of thin air, and every time the hunters make progress, more spring up to refill their ranks. Calor cannot say what evil power draws them to this unhappy realm, and puts his faith in Master Carevin to get to the bottom of it.', 'quest 173 reward text; quest 221 reward text'),
(1028, 2, 0, 255, 'Jonathan pointed to the mine to the south, Roland''s Doom, where the worgen were first found. There a mound of earth gave up the spirit of Velinde Starsong, a night elf priestess who had prayed for power against the demons of Felwood and been granted a scythe by Elune. She died there, lamenting her failure: the worgen run rampant, the Scythe of her goddess is lost, and she cannot say whose hand now directs its power. The Carevins mean to contain the evil she unleashed.', 'quest 1043 description and reward text; creature_text 3946 (Velinde Starsong''s spirit); gameobject 19030 Mound of Dirt at Roland''s Doom, event_script 664 summons Velinde''s spirit; warcraft.wiki.gg/wiki/Velinde_Starsong (died at Roland''s Doom)'),
(1028, 3, 0, 255, 'The mine holds another tale. A digger named Jitters, working Roland''s Doom for the Defias Brotherhood, pulled the haft of a rune-carved scythe from a pile of rubble, and a change rippled through the tunnels. Then the worgen came, clawing from hidden holes and dropping from above, and half the men fell in the first minutes. Jitters fled, losing the scythe in his flight, and fears it was he who brought the worgen upon Duskwood.', 'page_text 185-191 (Jitters'' Completed Journal)'),
(1029, 1, 0, 255, 'The mound held a small, dirt-stained book. Sven read its pages and slammed it shut: the shadowy figure had been a witness to his family''s death. He has questions to ask that man, if only he knew who he was, and he hopes someone in Darkshire can link the book with its owner.', 'quest 230 reward text; quest 262 description'),
(1029, 2, 0, 255, 'Madame Eva sensed that the book''s owner was a stranger to Darkshire, though the book itself was bought there. Clerk Daltry remembered selling it a month before to a nervous, jittery man always looking over his shoulder, and Tavernkeep Smitts recalled him writing at the bar each night before fleeing west, muttering of being hunted. In the empty town of Raven Hill, Jitters admitted the book was his.', 'quests 262, 265, 266 reward texts; quest 453 reward text'),
(1029, 3, 0, 255, 'Rather than face Sven, Jitters gave up his completed journal. It told of the Scythe of Elune and the riders who killed for it, and it set Sven on the path against them, for he had seen those riders with the necromancer Morbent Fel at the Forlorn Rowe. Fel''s death would be his revenge, though first he would test the skill of anyone he sent against so vile a fiend.', 'quest 268 description and reward text; quest 323 description'),
(1029, 4, 0, 255, 'Fel would not fall to ordinary blows. Bishop Farthing warned that the necromancer had cast dark enchantments about himself, and sent the would-be avenger to Menethil Harbor, where Lightforge iron lay in the wreck of the Flying Osprey, lost with the Third Fleet of Kul Tiras. Murlocs had stolen most of the ingots, but they were won back, and the dwarven smith Grimand Elmore in Stormwind forged them into Morbent''s Bane.', 'quests 269, 270, 321, 324, 322, 325 descriptions and reward texts'),
(1029, 5, 0, 255, 'Morbent''s Bane broke the necromancer''s protections, and Morbent Fel was defeated in his lair above the cemetery. The Dark Riders are still at large, but Sven, who had hoped beyond hope, saw a small piece of his revenge come to pass, and promised that the deed would live forever in the legends of Duskwood.', 'quest 55 description and reward text'),
(1030, 1, 0, 255, 'Lord Ebonlocke did not know him, and the note was written in an ancient script. Translated by the historian Sirra Von''Indi, it was a gloating confession: the Embalmer had tricked his helpers into building a fiend of flesh, bone and twisted metal, which waited outside his dwelling for the word to slaughter. As Sirra finished, the air grew heavy over the land, and Ello told the bearer that their kindness had doomed the town.', 'quests 160, 251, 401, 252 descriptions and reward texts; page_text 235'),
(1030, 2, 0, 255, 'The abomination Stitches marched on Darkshire along the road, roaring its hunger for the town. It overran the Night Watch camp on the way, and the town crier called the defenders to gather in the center of town, where together they stood against the undead monster until the beast was slain.', 'creature_text 412 (DARKSHIRE... I HUNGER); creature_text 468 (Town Crier during the Stitches event); smart_scripts 263 and 412 (finishing quest 252 starts the Stitches march)'),
(1030, 3, 0, 255, 'The Embalmer, Ello explained, is a name from one of Darkshire''s children''s stories: a kindly alchemist driven mad by the death of his wife Eliza, who used dark magic to place his own heart within her body. It revived her but cursed her with a hunger for human flesh, and he had to keep her buried. His heart is his power, and Ello wanted it out of her grave.', 'quest 253 description'),
(1030, 4, 0, 255, 'In the grave lay the remains of a coffin, and within it clawed fingers scraped and rotted teeth gnashed. The Embalmer''s heart was carried out still beating, and its magic became proof against his evil and a powerful aegis over Darkshire. Ello promised the deed a place in the town''s annals forever.', 'quest 254 reward text; quest 253 reward text'),
(1031, 1, 0, 255, 'Sirra Von''Indi knew Morgan well before he left for the war, a noble and good man who suffered a bad end. Sirra keeps a leatherbound book that tells his tale better than any memory can, and says that Commander Ebonlocke is the one who has handled the trouble with him of late.', 'quest 225 reward text; quest 227 description'),
(1031, 2, 0, 255, 'The book tells of a knight who fought beside Uther the Lightbringer in Lordaeron and came home to a corrupted forest and his family''s graves at Raven Hill. In his grief he killed three innocent attendants, then took his own life. Buried without ceremony, he could not rest, and days later his body was gone from the grave.', 'quest 225 reward text; page_text 64-72; quest 227 reward item 2154, page_text 64 to 72'),
(1031, 3, 0, 255, 'Commander Ebonlocke knows the rest. The undead thing calling itself Mor''Ladim that wanders the cemetery is Morgan''s body, attacking her watchmen on patrol and killing people, and she wants him laid to rest. Her scouts say he follows a strange and meandering path through the graves.', 'quest 227 reward text; quest 228 description'),
(1031, 4, 0, 255, 'When Mor''Ladim fell, Althea admitted what she should have said earlier. Morgan had believed all his family dead, but his daughter Sarah Ladimore had lived, and now serves as a Watcher, always troubled by the circumstances of her father''s death.', 'quest 228 reward text; quest 229 description'),
(1031, 5, 0, 255, 'Sarah slid a ring from her hand and asked that it be laid on her father''s grave, so that he might know she was well and that none of them held him responsible. At the grave a ghostly voice sounded on the wind. Morgan''s spirit, the weight lifted from it, gave his sword Archeus, forged to do good, to the one who brought word, and spoke his wife''s name as his soul was put to rest.', 'quest 229 reward text; quest 231 description and reward text');
